function renderNextWork(){const box=$('nextwork');if(!box||!me)return;let rows=[],title='',desc='';if(me.role==='ESTACIONADOS'){rows=shipments.filter(s=>s.archived!==true&&['SOLICITADO','LOCALIZANDO','PREPARADO','INCIDENCIA'].includes(s.status));title='Qué hacer ahora';desc='Solicitudes que requieren atención en Estacionados.'}else if(me.role==='RECEPCION'){rows=shipments.filter(s=>s.archived!==true&&['PENDIENTE_RECEPCION','EN_RECEPCION'].includes(s.status));title='Qué hacer ahora';desc='Envíos que requieren una acción en Recepción.'}else{rows=shipments.filter(s=>s.archived!==true&&s.status!=='ENTREGADO');title='Operativa pendiente';desc='Expedientes activos que todavía no han finalizado.'}rows.sort((a,b)=>(b.priority==='URGENTE')-(a.priority==='URGENTE')||new Date(a.requested_at)-new Date(b.requested_at));const items=rows.slice(0,5);let body='';if(items.length){body=items.map(s=>'<button class="nextitem" data-sid="'+esc(s.id)+'" onclick="detail(this.dataset.sid)"><span class="nextmain"><b>'+esc(s.tracking)+'</b><small>'+esc(s.customer_name)+' · '+esc(s.package_location)+'</small></span>'+statusTag(s.status)+'<span class="dasharrow">›</span></button>').join('')}else{const action=me.role==='RECEPCION'?'<button class="btn" onclick="go(\'new\')">Crear solicitud</button>':me.role==='ESTACIONADOS'?'<button class="btn btn2" onclick="go(\'stock\')">Consultar stock</button>':'<button class="btn btn2" onclick="go(\'reports\')">Ver informes</button>';body='<div class="nextempty"><span>✓</span><div><b>Todo al día</b><small>No hay tareas pendientes para tu perfil.</small></div>'+action+'</div>'}box.innerHTML='<div class="panelhead"><div><span class="eyebrow">PRIORIDAD</span><h2>'+esc(title)+'</h2><p>'+esc(desc)+'</p></div><button class="textbtn" onclick="go(\'work\')">Abrir bandeja →</button></div><div class="nextlist">'+body+'</div>'}
