function unlockNotifyAudio(){if(!soundEnabled)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;if(!notifyAudioCtx)notifyAudioCtx=new C();if(notifyAudioCtx.state==='suspended')notifyAudioCtx.resume()}catch(e){}}
function playNotifySound(kind='info'){if(!soundEnabled)return;unlockNotifyAudio();if(!notifyAudioCtx||notifyAudioCtx.state!=='running')return;const tones=kind==='request'?[880,880]:kind==='ready'?[660,880]:[520,520];tones.forEach((hz,i)=>{const o=notifyAudioCtx.createOscillator(),g=notifyAudioCtx.createGain(),t=notifyAudioCtx.currentTime+i*.18;o.frequency.value=hz;o.type='sine';g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.13,t+.015);g.gain.exponentialRampToValueAtTime(.0001,t+.12);o.connect(g);g.connect(notifyAudioCtx.destination);o.start(t);o.stop(t+.13)})}
function showToast(title,body='',kind='info'){const stack=$('toaststack');if(!stack)return;const el=document.createElement('div');el.className='toast '+kind;el.innerHTML='<b>'+esc(title)+'</b>'+(body?'<div>'+esc(body)+'</div>':'');stack.appendChild(el);setTimeout(()=>el.classList.add('show'),10);setTimeout(()=>{el.classList.remove('show');setTimeout(()=>el.remove(),220)},6500)}
async function enableDeviceNotifications(){unlockNotifyAudio();soundEnabled=true;localStorage.setItem('envios_sound','1');if(!('Notification'in window))return showToast('Avisos sonoros activados','Este navegador no admite notificaciones del dispositivo.','info');if(Notification.permission==='granted')return showToast('Avisos activados','Sonido y notificaciones del dispositivo están activos.','ok');const p=await Notification.requestPermission();showToast(p==='granted'?'Avisos activados':'Avisos del dispositivo no activados',p==='granted'?'Recibirás avisos también cuando la pestaña esté en segundo plano.':'El sonido y los avisos dentro de la web seguirán funcionando mientras esté abierta.',p==='granted'?'ok':'warn')}
function deviceNotify(title,body){if(document.hidden&&'Notification'in window&&Notification.permission==='granted'){try{new Notification(title,{body:'Abre el sistema para consultar los detalles.',tag:'envios-operativa'})}catch(e){}}}
function queueRealtimeNotice(kind,title,body){const b=notifyBursts[kind];if(!b)return;b.count++;b.last={title,body};if(b.timer)clearTimeout(b.timer);b.timer=setTimeout(()=>{const count=b.count,last=b.last;b.count=0;b.timer=null;b.last=null;let t=last.title,msg=last.body;if(count>1){if(kind==='request'){t=count+' nuevas solicitudes de Recepción';msg='Hay '+count+' envíos nuevos esperando en la bandeja de Estacionados.'}else if(kind==='ready'){t=count+' envíos listos para Recepción';msg='Estacionados ha transferido '+count+' envíos. Revisa la bandeja.'}else{t=count+' nuevas incidencias';msg='Revisa las incidencias abiertas.'}}playNotifySound(kind);showToast(t,msg,kind);deviceNotify(t,msg)},650)}
async function handleShipmentRealtime(payload){const n=payload.new||{},o=payload.old||{};if(['ESTACIONADOS','ADMIN'].includes(me?.role)&&n.status==='SOLICITADO'&&o.status!=='SOLICITADO')queueRealtimeNotice('request','Nueva solicitud de Recepción',(n.tracking||'Envío')+' · '+(n.package_location||''));else if(['RECEPCION','ADMIN'].includes(me?.role)&&n.status==='PENDIENTE_RECEPCION'&&o.status!=='PENDIENTE_RECEPCION')queueRealtimeNotice('ready','Envío listo para Recepción',(n.tracking||'Envío')+' · Estacionados ha realizado la transferencia.');else if(n.status==='INCIDENCIA'&&o.status!=='INCIDENCIA')queueRealtimeNotice('warn','Nueva incidencia',(n.tracking||'Envío')+' · '+(n.incident_reason||'Revisar expediente.'));await refresh()}
function updateOperationalAlert(){const box=$('opsalert');if(!box||!me)return;const active=shipments.filter(s=>s.archived!==true);let count=0,msg='';if(me.role==='ESTACIONADOS'){count=active.filter(s=>s.status==='SOLICITADO').length;msg=count===1?'1 solicitud nueva pendiente de localizar.':count+' solicitudes nuevas pendientes de localizar.'}else if(me.role==='RECEPCION'){count=active.filter(s=>s.status==='PENDIENTE_RECEPCION').length;msg=count===1?'1 envío está listo para recibir desde Estacionados.':count+' envíos están listos para recibir desde Estacionados.'}else{const a=active.filter(s=>s.status==='SOLICITADO').length,b=active.filter(s=>s.status==='PENDIENTE_RECEPCION').length;count=a+b;msg=a+' solicitudes pendientes en Estacionados · '+b+' listas para Recepción.'}[$('navworkbadge'),$('mobileworkbadge')].forEach(x=>{if(!x)return;x.textContent=count>99?'99+':String(count);x.classList.toggle('hide',count===0)});if(count>0){box.classList.remove('hide');box.innerHTML='<div><b>Atención operativa</b><span>'+esc(msg)+'</span></div><button class="btn" onclick="go(\'work\')">Abrir bandeja</button>';document.title='🔔 '+count+' pendiente'+(count===1?'':'s')+' · Envíos'}else{box.classList.add('hide');box.innerHTML='';document.title='Envíos · Recepción / Estacionados'}}

function searchResults(){const q=$('search')?.value.trim().toLowerCase()||'',st=$('statusfilter')?.value||'',af=$('archivefilter')?.value||'active',df=$('datefrom')?.value||'',dt=$('dateto')?.value||'';return shipments.filter(s=>{const day=(s.requested_at||'').slice(0,10);const text=[s.tracking,s.customer_name,s.package_location,s.recipient_name,s.recipient_id,s.status,s.notes,s.incident_reason,s.external_reference].some(v=>(v||'').toLowerCase().includes(q));const archiveOk=af==='all'||(af==='archived'?s.archived===true:s.archived!==true);return archiveOk&&(!st||s.status===st)&&(!df||day>=df)&&(!dt||day<=dt)&&text})}
function render(){if(!$('rows'))return;const f=searchResults();$('resultcount').textContent=f.length+' envío(s) encontrado(s)';$('rows').innerHTML=f.map(s=>{let a='<button class="btn btn2" onclick="detail(\''+s.id+'\')">Ver expediente</button>';if(['ESTACIONADOS','ADMIN'].includes(me.role)&&s.status==='SOLICITADO')a+='<button class="btn" onclick="setStatus(\''+s.id+'\',\'LOCALIZANDO\')">Localizando</button>';if(['ESTACIONADOS','ADMIN'].includes(me.role)&&s.status==='LOCALIZANDO')a+='<button class="btn" onclick="prepare(\''+s.id+'\')">Preparado</button>';if(['ESTACIONADOS','ADMIN'].includes(me.role)&&['PREPARADO','INCIDENCIA'].includes(s.status))a+='<button class="btn ok" onclick="handoff(\''+s.id+'\')">A Recepción</button>';if(['RECEPCION','ADMIN'].includes(me.role)&&s.status==='PENDIENTE_RECEPCION')a+='<button class="btn ok" onclick="confirmReception(\''+s.id+'\')">Confirmar</button>';if(['RECEPCION','ADMIN'].includes(me.role)&&s.status==='EN_RECEPCION')a+='<button class="btn ok" onclick="deliver(\''+s.id+'\')">Entregar</button>';if(s.status!=='ENTREGADO')a+='<button class="btn danger" onclick="incident(\''+s.id+'\')">Incidencia</button>';if(me.role==='ADMIN'){a+='<button class="btn btn2" onclick="correctShipment(\''+s.id+'\')">Corregir</button>';a+='<button class="btn btn2" onclick="toggleArchive(\''+s.id+'\')">'+(s.archived?'Restaurar':'Archivar')+'</button>'}a+='<button class="btn btn2" onclick="printShipment(\''+s.id+'\')">Imprimir</button>';return '<tr class="rowclick"><td><b>'+esc(s.tracking)+'</b></td><td>'+esc(s.customer_name)+'</td><td>'+esc(s.package_location)+'</td><td>'+esc(s.requested_at?new Date(s.requested_at).toLocaleDateString():'—')+'</td><td>'+esc(s.recipient_name||'—')+'</td><td><span class="tag '+(s.priority==='URGENTE'?'urgent':'')+'">'+esc(s.priority)+'</span></td><td>'+statusTag(s.status)+'</td><td><div class="actions">'+a+'</div></td></tr>'}).join('')||'<tr><td colspan="8" class="muted">No hay envíos que coincidan con la búsqueda.</td></tr>'}
function clearSearch(){if($('search'))$('search').value='';if($('statusfilter'))$('statusfilter').value='';if($('archivefilter'))$('archivefilter').value='active';if($('datefrom'))$('datefrom').value='';if($('dateto'))$('dateto').value='';render()}
function workItems(){const st=$('workfilter')?.value||'',sort=$('worksort')?.value||'age';let allowed=me?.role==='ESTACIONADOS'?['SOLICITADO','LOCALIZANDO','PREPARADO','INCIDENCIA']:me?.role==='RECEPCION'?['PENDIENTE_RECEPCION','EN_RECEPCION']:['SOLICITADO','LOCALIZANDO','PREPARADO','PENDIENTE_RECEPCION','EN_RECEPCION','INCIDENCIA'];const rows=shipments.filter(s=>s.archived!==true&&s.status!=='ENTREGADO').filter(s=>(!st&&allowed.includes(s.status))||(st&&s.status===st));return rows.sort((a,b)=>{const urgent=(b.priority==='URGENTE')-(a.priority==='URGENTE');if(urgent)return urgent;if(sort==='location'){const ka=[a.stock_snapshot?.aisle||'',a.stock_snapshot?.shelf_column||'',a.stock_snapshot?.height||'',a.stock_snapshot?.route||'',a.tracking||''].join('|'),kb=[b.stock_snapshot?.aisle||'',b.stock_snapshot?.shelf_column||'',b.stock_snapshot?.height||'',b.stock_snapshot?.route||'',b.tracking||''].join('|');const c=ka.localeCompare(kb,'es',{numeric:true,sensitivity:'base'});if(c)return c}return new Date(a.requested_at)-new Date(b.requested_at)})}
function waitingTime(s){const start=s.status==='EN_RECEPCION'?(s.reception_at||s.requested_at):s.status==='PENDIENTE_RECEPCION'?(s.handoff_at||s.requested_at):s.prepared_at||s.requested_at;if(!start)return '—';const h=Math.max(0,Math.floor((Date.now()-new Date(start))/3600000));return h<24?h+' h':Math.floor(h/24)+' d '+(h%24)+' h'}
function renderWork(){if(!$('workrows'))return;const f=workItems();const urgent=f.filter(s=>s.priority==='URGENTE').length;$('workcount').textContent=f.length+' envío(s) pendiente(s)'+(urgent?' · '+urgent+' urgente(s)':'');$('workrows').innerHTML=f.map(s=>{const route=s.stock_snapshot?.route||'';return '<tr><td><input class="worksel" type="checkbox" value="'+esc(s.id)+'"></td><td><b>'+esc(s.tracking)+'</b>'+(s.priority==='URGENTE'?'<br><span class="tag urgent">URGENTE</span>':'')+'</td><td>'+esc(s.customer_name)+'</td><td>'+esc(s.package_location)+(route?'<br><span class="muted">Recorrido '+esc(route)+'</span>':'')+'</td><td>'+statusTag(s.status)+'</td><td>'+esc(waitingTime(s))+'</td><td><button class="btn btn2" data-sid="'+esc(s.id)+'" onclick="detail(this.dataset.sid)">Ver</button></td></tr>'}).join('')||'<tr><td colspan="7" class="muted">No hay envíos pendientes para este filtro.</td></tr>'}
function quickFindKey(e){if(e.key==='Enter'){e.preventDefault();quickFind()}}
async function quickFind(){const input=$('quickfind'),q=input?.value.trim();if(!q)return;const exact=shipments.find(s=>String(s.tracking).trim().toLowerCase()===q.toLowerCase());if(exact){input.value='';return detail(exact.id)}const st=await lookupStock(q);if(st){input.value='';if(['RECEPCION','ADMIN'].includes(me.role))return applyStockToNew(st);go('stock');await loadStock();$('stocksearch').value=st.tracking;renderStock();return}go('shipments');$('search').value=q;render();setTimeout(()=>$('search')?.focus(),50)}
const STOCK_HEADERS=['Bulto','Pasillo','Columna','Altura','Recorrido','Agencia','C. Usuario','F. Ubicación','CP Destino','Destinatario','Tipo Incidencia','Agencia Cargo','Cliente'];
function stockLocation(s){return [s.aisle?'Pasillo '+s.aisle:'',s.shelf_column?'Columna '+s.shelf_column:'',s.height?'Altura '+s.height:''].filter(Boolean).join(' · ')}
function stockSnapshot(s){return {tracking:s.tracking,aisle:s.aisle,shelf_column:s.shelf_column,height:s.height,route:s.route,agency:s.agency,location_user:s.location_user,located_at:s.located_at,destination_postcode:s.destination_postcode,recipient_name:s.recipient_name,incident_type:s.incident_type,charge_agency:s.charge_agency,client_code:s.client_code}}
function stockCardHtml(s,actions=''){return '<div class="card stockcard"><div class="stockhead"><div><span class="muted">Bulto</span><h3>'+esc(s.tracking)+'</h3></div><span class="tag">'+esc(s.route||'Sin recorrido')+'</span></div><div class="stockgrid"><div><b>Destinatario</b><br>'+esc(s.recipient_name||'—')+'</div><div><b>Ubicación</b><br>'+esc(stockLocation(s)||'—')+'</div><div><b>CP destino</b><br>'+esc(s.destination_postcode||'—')+'</div><div><b>Incidencia</b><br>'+esc(s.incident_type||'—')+'</div><div><b>Agencia</b><br>'+esc(s.agency||'—')+'</div><div><b>Cliente</b><br>'+esc(s.client_code||'—')+'</div><div><b>Ubicado por</b><br>'+esc(s.location_user||'—')+'</div><div><b>Fecha ubicación</b><br>'+esc(s.located_at?fmtDate(s.located_at):'—')+'</div></div>'+(actions?'<div class="actions stockactions">'+actions+'</div>':'')+'</div>'}
async function lookupStock(code){const q=String(code||'').trim();if(!q)return null;const {data,error}=await sb.from('warehouse_stock').select('*').eq('tracking',q).maybeSingle();if(error){console.error(error);return null}return data||null}
function applyStockToNew(s){currentStockMatch=s;go('new');$('tracking').value=s.tracking||'';$('customer').value=s.recipient_name||'';$('location').value=stockLocation(s);if($('stockmatch'))$('stockmatch').innerHTML=stockCardHtml(s,'<span class="stockok">Datos cargados desde el stock actual</span>');setTimeout(()=>$('priority')?.focus(),50)}
async function lookupNewStock(showMissing=true){const code=$('tracking')?.value.trim();if(!code)return;const st=await lookupStock(code);if(st)return applyStockToNew(st);currentStockMatch=null;if($('stockmatch'))$('stockmatch').innerHTML=showMissing?'<div class="stockmissing">No figura en el stock actual. Puedes completar la solicitud manualmente.</div>':''}
function stockNewKey(e){if(e.key==='Enter'){e.preventDefault();lookupNewStock(true)}}
function fastMode(){return document.querySelector('input[name="fastmode"]:checked')?.value||'queue'}
function setFastMode(v){localStorage.setItem('envios_fastmode',v);if($('fasttracking'))setTimeout(()=>$('fasttracking').focus(),20)}
function initFastMode(){const v=localStorage.getItem('envios_fastmode')||'queue';const x=document.querySelector('input[name="fastmode"][value="'+v+'"]');if(x)x.checked=true;renderFastQueue()}
function fastRequestKey(e){if(e.key==='Enter'){e.preventDefault();fastRequestAdd()}}
async function fastRequestAdd(){if(!['RECEPCION','ADMIN'].includes(me?.role))return;const input=$('fasttracking'),code=input?.value.trim();if(!code)return;const existing=shipments.find(s=>String(s.tracking).trim().toLowerCase()===code.toLowerCase());if(existing){$('fastfeedback').innerHTML='<div class="fastwarn"><b>Este envío ya está solicitado.</b><br>'+esc(existing.tracking)+' · '+esc(labels[existing.status]||existing.status)+' <button class="btn btn2" data-sid="'+esc(existing.id)+'" onclick="detail(this.dataset.sid)">Ver expediente</button></div>';input.select();return}const st=await lookupStock(code);if(!st){$('fastfeedback').innerHTML='<div class="stockmissing"><b>No figura en el stock actual.</b><br>Comprueba el número o utiliza la solicitud manual si procede.</div>';input.select();return}if(fastMode()==='instant'){input.value='';await createFastRequests([st.tracking],true);input.focus();return}if(quickRequestQueue.some(x=>String(x.tracking).toLowerCase()===String(st.tracking).toLowerCase())){$('fastfeedback').innerHTML='<div class="fastwarn">El envío '+esc(st.tracking)+' ya está en la lista.</div>';input.value='';input.focus();return}if(quickRequestQueue.length>=100)return alert('La lista rápida admite un máximo de 100 envíos.');quickRequestQueue.push(st);$('fastfeedback').innerHTML='<div class="fastok">Añadido: <b>'+esc(st.tracking)+'</b> · '+esc(st.recipient_name||'Sin destinatario')+'</div>';input.value='';renderFastQueue();input.focus()}
function renderFastQueue(){if(!$('fastqueue'))return;const n=quickRequestQueue.length;if($('fastqueuecount'))$('fastqueuecount').textContent=n;$('fastsend').disabled=n===0;$('fastclear').disabled=n===0;$('fastqueue').innerHTML=n?'<div class="fastqueuehead"><b>'+n+' envío'+(n===1?'':'s')+' preparado'+(n===1?'':'s')+'</b><span class="muted">Se registrarán juntos al pulsar Enviar solicitudes</span></div>'+quickRequestQueue.map((s,i)=>'<div class="fastitem"><div><b>'+esc(s.tracking)+'</b><span>'+esc(s.recipient_name||'Sin destinatario')+'</span><small>'+esc(stockLocation(s)||'Sin ubicación')+(s.route?' · Recorrido '+esc(s.route):'')+'</small></div><button class="btn btn2" onclick="removeFastQueue('+i+')">Quitar</button></div>').join(''):'<div class="fastempty">Escanea varios envíos y aparecerán aquí antes de enviarlos.</div>'}
function removeFastQueue(i){quickRequestQueue.splice(i,1);renderFastQueue();$('fasttracking')?.focus()}
function clearFastQueue(){quickRequestQueue=[];renderFastQueue();if($('fastfeedback'))$('fastfeedback').innerHTML='';$('fasttracking')?.focus()}
async function createFastRequests(trackings,instant=false){if(!trackings.length)return;const {data,error}=await sb.rpc('create_stock_requests',{p_trackings:trackings});if(error){showToast('No se pudo crear la solicitud',error.message,'warn');if($('fastfeedback'))$('fastfeedback').innerHTML='<div class="stockmissing">'+esc(error.message)+'</div>';return false}showToast(data.count===1?'Solicitud registrada':'Solicitudes registradas',data.count+' envío'+(data.count===1?'':'s')+' enviado'+(data.count===1?'':'s')+' a Estacionados.','ok');if($('fastfeedback'))$('fastfeedback').innerHTML='<div class="fastok"><b>Correcto.</b> '+data.count+' solicitud'+(data.count===1?'':'es')+' registrada'+(data.count===1?'':'s')+'.'+(data.batch_code?' Lote '+esc(data.batch_code)+'.':'')+'</div>';if(!instant)quickRequestQueue=[];renderFastQueue();await refresh();return true}
async function sendFastQueue(){if(!quickRequestQueue.length)return;if(!confirm('¿Enviar '+quickRequestQueue.length+' solicitud'+(quickRequestQueue.length===1?'':'es')+' a Estacionados?'))return;const trackings=quickRequestQueue.map(x=>x.tracking);const ok=await createFastRequests(trackings,false);if(ok)$('fasttracking')?.focus()}

function excelStockDate(v){if(v===null||v===undefined||v==='')return null;if(typeof v==='number'&&window.XLSX?.SSF?.parse_date_code){const d=XLSX.SSF.parse_date_code(v);if(!d)return null;const p=n=>String(n).padStart(2,'0');return d.y+'-'+p(d.m)+'-'+p(d.d)+'T'+p(d.H||0)+':'+p(d.M||0)+':'+p(Math.round(d.S||0))}if(v instanceof Date){const p=n=>String(n).padStart(2,'0');return v.getFullYear()+'-'+p(v.getMonth()+1)+'-'+p(v.getDate())+'T'+p(v.getHours())+':'+p(v.getMinutes())+':'+p(v.getSeconds())}const s=String(v).trim();return s||null}
function parseStockFile(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onerror=()=>reject(new Error('No se pudo leer el archivo.'));r.onload=()=>{try{if(!window.XLSX)throw new Error('No se ha cargado el lector de Excel.');const wb=XLSX.read(r.result,{type:'array',cellDates:false});const ws=wb.Sheets[wb.SheetNames[0]],raw=XLSX.utils.sheet_to_json(ws,{header:1,raw:true,defval:''});if(!raw.length)throw new Error('El archivo está vacío.');const hdr=STOCK_HEADERS.map((_,i)=>String(raw[0][i]??'').trim());if(STOCK_HEADERS.some((h,i)=>hdr[i]!==h))throw new Error('El formato no coincide con el Stock de Almacén esperado. Revisa las 13 columnas y sus cabeceras.');const out=[],seen=new Set();for(let i=1;i<raw.length;i++){const x=raw[i];const tracking=String(x[0]??'').trim();if(!tracking)continue;if(seen.has(tracking))throw new Error('Bulto duplicado en el archivo: '+tracking);seen.add(tracking);out.push({tracking,aisle:String(x[1]??'').trim(),shelf_column:String(x[2]??'').trim(),height:String(x[3]??'').trim(),route:String(x[4]??'').trim(),agency:String(x[5]??'').trim(),location_user:String(x[6]??'').trim(),located_at:excelStockDate(x[7]),destination_postcode:String(x[8]??'').trim(),recipient_name:String(x[9]??'').trim(),incident_type:String(x[10]??'').trim(),charge_agency:String(x[11]??'').trim(),client_code:String(x[12]??'').trim()})}if(!out.length)throw new Error('No se encontraron bultos válidos.');if(out.length>10000)throw new Error('El archivo supera el máximo de 10.000 bultos.');resolve(out)}catch(e){reject(e)}};r.readAsArrayBuffer(file)})}
async function importWarehouseStock(){if(!['ESTACIONADOS','ADMIN'].includes(me?.role))return alert('Solo ADMIN o ESTACIONADOS pueden actualizar el stock.');const input=document.createElement('input');input.type='file';input.accept='.xlsx,.xls,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel';input.onchange=async()=>{const f=input.files?.[0];if(!f)return;if(f.size>20*1024*1024)return alert('El archivo de stock supera 20 MB.');try{if($('stockimportstatus'))$('stockimportstatus').textContent='Leyendo y validando '+f.name+'…';const rows=await parseStockFile(f);if(!confirm('Se sustituirá el stock operativo actual por '+rows.length+' bultos de '+f.name+'. ¿Continuar?')){if($('stockimportstatus'))$('stockimportstatus').textContent='Importación cancelada.';return}if($('stockimportstatus'))$('stockimportstatus').textContent='Actualizando stock…';const {data,error}=await sb.rpc('replace_warehouse_stock',{p_source_name:f.name,p_rows:rows});if(error)throw error;stockLoaded=false;if($('stockimportstatus'))$('stockimportstatus').textContent='Stock actualizado: '+data.row_count+' bultos.';await loadStock(true);alert('Stock actualizado correctamente: '+data.row_count+' bultos.')}catch(e){if($('stockimportstatus'))$('stockimportstatus').textContent='Error: '+e.message;alert(e.message)}};input.click()}
async function loadStock(force=false){if(stockLoaded&&!force)return renderStock();const [s,i]=await Promise.all([sb.from('warehouse_stock').select('*').order('aisle').order('shelf_column').order('height').limit(10000),sb.from('stock_imports').select('*').order('imported_at',{ascending:false}).limit(1).maybeSingle()]);if(s.error){$('stockcount').textContent='No se pudo cargar el stock.';return}stockRows=s.data||[];latestStockImport=i.data||null;stockLoaded=true;renderStock()}
function renderStock(){if(!$('stockrows'))return;const q=$('stocksearch')?.value.trim().toLowerCase()||'';const f=stockRows.filter(s=>[s.tracking,s.recipient_name,s.aisle,s.shelf_column,s.height,s.route,s.agency,s.destination_postcode,s.incident_type,s.client_code].some(v=>String(v||'').toLowerCase().includes(q)));$('stockcount').textContent=f.length+' bulto(s)'+(q?' encontrados':' en stock actual');if($('stocklast'))$('stocklast').textContent=latestStockImport?'Última actualización: '+fmtDate(latestStockImport.imported_at)+' · '+latestStockImport.source_name+' · '+latestStockImport.row_count+' bultos':'Todavía no se ha importado stock.';$('stockrows').innerHTML=f.slice(0,300).map(s=>'<tr><td><b>'+esc(s.tracking)+'</b></td><td>'+esc(s.recipient_name||'—')+'</td><td>'+esc(stockLocation(s)||'—')+'</td><td>'+esc(s.route||'—')+'</td><td>'+esc(s.incident_type||'—')+'</td><td>'+esc(s.destination_postcode||'—')+'</td><td>'+esc(s.client_code||'—')+'</td></tr>').join('')||'<tr><td colspan="7" class="muted">No hay bultos que coincidan.</td></tr>';if(f.length>300&&$('stocklimit'))$('stocklimit').textContent='Mostrando los primeros 300 resultados. Usa el buscador para acotar.';else if($('stocklimit'))$('stocklimit').textContent=''}

function toggleAllWork(on){document.querySelectorAll('.worksel').forEach(x=>x.checked=on)}
async function bulkAdvance(){const ids=[...document.querySelectorAll('.worksel:checked')].map(x=>x.value);if(!ids.length)return alert('Selecciona al menos un envío.');if(ids.length>100)return alert('Puedes avanzar un máximo de 100 envíos por operación.');if(!confirm('¿Avanzar '+ids.length+' envío(s)?'))return;const {data,error}=await sb.rpc('bulk_advance_shipments',{p_ids:ids});if(error)return alert(error.message);await refresh();alert((data?.updated||0)+' envío(s) actualizados'+((data?.skipped||0)?' · '+data.skipped+' sin cambio por su estado actual':'')+'.')}
async function ev(){return true}
async function createShipment(){const tracking=$('tracking').value.trim();const o={tracking,customer_name:$('customer').value.trim(),package_location:$('location').value.trim(),notes:$('notes').value.trim(),priority:$('priority').value,requested_by:me.id};if(currentStockMatch&&String(currentStockMatch.tracking).trim().toLowerCase()===tracking.toLowerCase()){o.stock_import_id=currentStockMatch.import_id;o.stock_snapshot=stockSnapshot(currentStockMatch)}if(!o.tracking||!o.customer_name||!o.package_location)return alert('Completa envío, cliente y ubicación.');const {data,error}=await sb.from('shipments').insert(o).select('id,tracking').single();if(error)return alert(error.message);await ev(data.id,'SOLICITUD_CREADA',o.stock_snapshot?'Solicitud registrada desde stock de almacén':'Solicitud registrada');['tracking','customer','location','notes'].forEach(x=>$(x).value='');currentStockMatch=null;if($('stockmatch'))$('stockmatch').innerHTML='';await refresh();alert('Solicitud registrada.')}
async function createBulk(){const lines=$('bulk').value.split(/\n/).map(x=>x.trim()).filter(Boolean);if(!lines.length)return alert('Introduce solicitudes.');if(lines.length>500)return alert('El registro múltiple admite un máximo de 500 envíos por operación.');const rows=[];for(const line of lines){const p=line.split(';').map(x=>x.trim());if(p.length<3||!p[0]||!p[1]||!p[2])return alert('Formato incorrecto: '+line);rows.push({tracking:p[0],customer_name:p[1],package_location:p[2],notes:p.slice(3).join('; '),priority:'NORMAL'})}const title=$('batchtitle')?.value.trim()||'',bnotes=$('batchnotes')?.value.trim()||'';const {data,error}=await sb.rpc('create_manual_requests',{p_rows:rows,p_title:title||null,p_notes:bnotes||null,p_source:null});if(error)return alert(error.message);$('bulk').value='';if($('batchtitle'))$('batchtitle').value='';if($('batchnotes'))$('batchnotes').value='';await refresh();alert((data?.count||rows.length)+' solicitudes registradas'+(data?.batch_code?' en '+data.batch_code:'')+'.')}
async function setStatus(id,status){const {error}=await sb.from('shipments').update({status}).eq('id',id);if(error)return alert(error.message);await ev(id,status,'Cambio de estado');refresh()}
async function prepare(id){const {error}=await sb.from('shipments').update({status:'PREPARADO',prepared_by:me.id,prepared_at:now()}).eq('id',id);if(error)return alert(error.message);await ev(id,'PREPARADO','Envío preparado en Estacionados');refresh()}
async function handoff(id){if(!confirm('¿Confirmas la entrega física a Recepción?'))return;const {error}=await sb.from('shipments').update({status:'PENDIENTE_RECEPCION',warehouse_by:me.id,warehouse_at:now(),handoff_at:now()}).eq('id',id);if(error)return alert(error.message);await ev(id,'ENTREGADO_POR_ESTACIONADOS','Pendiente de confirmación de Recepción');refresh()}
async function confirmReception(id){if(!confirm('¿Recepción tiene físicamente el paquete?'))return;const {error}=await sb.from('shipments').update({status:'EN_RECEPCION',reception_by:me.id,reception_at:now(),reception_confirmed_at:now()}).eq('id',id);if(error)return alert(error.message);await ev(id,'RECIBIDO_EN_RECEPCION','Custodia confirmada');refresh()}
function looksLikePersonName(v){const x=String(v||'').trim().replace(/\s+/g,' ');if(!x)return false;if(/[+_]/.test(x))return false;if(/\d/.test(x)&&!x.includes(' '))return false;if(/^[A-Z0-9./-]+$/i.test(x)&&/\d/.test(x))return false;return /[A-Za-zÁÉÍÓÚÜÑáéíóúüñ]/.test(x)}
function deliveryNameSuggestion(s){const stock=String(s.stock_snapshot?.recipient_name||'').trim(),customer=String(s.customer_name||'').trim();if(looksLikePersonName(stock))return {name:stock,source:'stock',raw:stock};if(looksLikePersonName(customer))return {name:customer,source:'expediente',raw:stock||customer};return {name:'',source:'none',raw:stock||customer}}
function deliver(id){const s=shipments.find(x=>x.id===id);if(!s)return;deliveryShipmentId=id;const info=deliveryNameSuggestion(s);$('deliverytracking').textContent=s.tracking;$('deliveryname').value=info.name;$('deliveryid').value='';const raw=info.raw||'';if(info.source==='stock'){$('deliveryhint').innerHTML='Destinatario cargado automáticamente desde el stock: <b>'+esc(info.name)+'</b>. Puedes borrarlo y escribir otro si recoge una persona diferente.';$('deliveryhint').className='fieldhint good'}else if(info.source==='expediente'){$('deliveryhint').innerHTML='Nombre cargado desde el expediente: <b>'+esc(info.name)+'</b>. Puedes modificarlo si recoge otra persona.';$('deliveryhint').className='fieldhint good'}else if(raw){$('deliveryhint').innerHTML='En el stock figura <b>'+esc(raw)+'</b>, pero parece un código y no un nombre de persona. Escribe quién recoge realmente el envío.';$('deliveryhint').className='fieldhint warn'}else{$('deliveryhint').textContent='El stock no contiene un nombre de persona. Escribe quién recoge realmente el envío.';$('deliveryhint').className='fieldhint warn'}$('deliverymodal').classList.add('open');setTimeout(()=>{$('deliveryname')?.focus();if($('deliveryname')?.value)$('deliveryname').select()},50)}
function closeDelivery(){deliveryShipmentId=null;$('deliverymodal')?.classList.remove('open')}
async function confirmDelivery(){const id=deliveryShipmentId,s=shipments.find(x=>x.id===id);if(!s)return closeDelivery();const n=$('deliveryname').value.trim(),dni=$('deliveryid').value.trim();if(!n)return showToast('Falta el nombre','Indica la persona que recoge el envío.','warn');$('deliveryconfirm').disabled=true;const {error}=await sb.from('shipments').update({status:'ENTREGADO',recipient_name:n,recipient_id:dni,delivered_by:me.id,delivered_at:now()}).eq('id',id);$('deliveryconfirm').disabled=false;if(error)return showToast('No se pudo registrar la entrega',error.message,'warn');await ev(id,'ENTREGA_FINAL','Entregado a '+n+(dni?' · ID '+dni:''));closeDelivery();await refresh();showToast('Entrega registrada',s.tracking+' · '+n,'ok')}
async function incident(id){const d=(prompt('Describe la incidencia:')||'').trim();if(!d)return;const {error}=await sb.from('shipments').update({status:'INCIDENCIA',incident_reason:d}).eq('id',id);if(error)return showToast('No se pudo abrir la incidencia',error.message,'warn');await refresh();showToast('Incidencia registrada','Ha quedado vinculada al expediente.','ok')}
function renderIncidents(){$('incidentlist').innerHTML=incs.filter(i=>!i.resolved).map(i=>{const s=shipments.find(x=>x.id===i.shipment_id);return '<div class="card"><b>'+esc(s?.tracking||'Envío')+'</b> · '+esc(s?.customer_name||'')+'<p>'+esc(i.detail)+'</p><span class="muted">'+new Date(i.created_at).toLocaleString()+'</span> <button class="btn ok" onclick="resolveIncident(\''+i.id+'\',\''+i.shipment_id+'\')">Resolver</button></div>'}).join('')||'<p class="muted">No hay incidencias abiertas.</p>'}
async function resolveIncident(iid,sid){const {error}=await sb.from('shipments').update({status:'LOCALIZANDO',incident_reason:null}).eq('id',sid);if(error)return showToast('No se pudo resolver la incidencia',error.message,'warn');await refresh();showToast('Incidencia resuelta','El envío vuelve a Localizando.','ok')}
async function toggleArchive(id){if(me?.role!=='ADMIN')return alert('Solo ADMIN puede archivar expedientes.');const s=shipments.find(x=>x.id===id);if(!s)return;const next=!s.archived;if(next&&s.status!=='ENTREGADO')return alert('Solo se pueden archivar envíos ya entregados.');const reason=(prompt(next?'Motivo del archivado:':'Motivo de la restauración:')||'').trim();if(!reason)return alert('Debes indicar un motivo.');if(!confirm(next?'¿Archivar este expediente? Seguirá conservándose y podrá consultarse desde el filtro Archivados.':'¿Restaurar este expediente al listado activo?'))return;const {error}=await sb.from('shipments').update({archived:next,archive_reason:reason}).eq('id',id);if(error)return alert(error.message);await refresh();alert(next?'Expediente archivado.':'Expediente restaurado.')}

async function correctShipment(id){if(me?.role!=='ADMIN')return alert('Solo ADMIN puede corregir expedientes.');const s=shipments.find(x=>x.id===id);if(!s)return;const customer=prompt('Cliente / destinatario:',s.customer_name||'');if(customer===null)return;const location=prompt('Ubicación física:',s.package_location||'');if(location===null)return;const notes=prompt('Observaciones:',s.notes||'');if(notes===null)return;const ref=prompt('Referencia externa:',s.external_reference||'');if(ref===null)return;const priority=(prompt('Prioridad: NORMAL o URGENTE',s.priority||'NORMAL')||'').trim().toUpperCase();if(!['NORMAL','URGENTE'].includes(priority))return alert('Prioridad no válida.');const reason=(prompt('Motivo obligatorio de la corrección:')||'').trim();if(!reason)return alert('Debes indicar el motivo de la corrección.');const changes=[];if(customer.trim()!==String(s.customer_name||''))changes.push('cliente');if(location.trim()!==String(s.package_location||''))changes.push('ubicación');if(notes.trim()!==String(s.notes||''))changes.push('observaciones');if(ref.trim()!==String(s.external_reference||''))changes.push('referencia externa');if(priority!==String(s.priority||'NORMAL'))changes.push('prioridad');if(!changes.length)return alert('No has modificado ningún dato.');const patch={customer_name:customer.trim(),package_location:location.trim(),notes:notes.trim(),external_reference:ref.trim(),priority,corrected_at:now(),corrected_by:me.id,correction_reason:reason};const {error}=await sb.from('shipments').update(patch).eq('id',id);if(error)return alert(error.message);await ev(id,'CORRECCION_ADMIN','Campos corregidos: '+changes.join(', ')+' · Motivo: '+reason);await refresh();await detail(id);alert('Corrección guardada y registrada en la trazabilidad.')}

function proofExt(file){const n=(file.name||'').toLowerCase();if(n.endsWith('.jpg')||n.endsWith('.jpeg'))return 'jpg';if(n.endsWith('.png'))return 'png';if(n.endsWith('.webp'))return 'webp';if(n.endsWith('.pdf'))return 'pdf';return 'bin'}
async function saveProofFile(shipment,file,method='DIRECT',detectedTracking=''){if(!shipment||shipment.status!=='ENTREGADO')throw new Error('Los justificantes se asocian a envíos ya entregados.');if(file.size>10*1024*1024)throw new Error(file.name+': supera 10 MB.');const allowed=new Set(['application/pdf','image/jpeg','image/png','image/webp']);if(!allowed.has(file.type))throw new Error(file.name+': tipo de archivo no permitido.');const ext=proofExt(file);if(ext==='bin')throw new Error(file.name+': extensión no permitida.');const path=shipment.id+'/'+crypto.randomUUID()+'.'+ext;const {error:upErr}=await sb.storage.from('proofs').upload(path,file,{upsert:false,contentType:file.type});if(upErr)throw upErr;const {error:dbErr}=await sb.from('shipment_proofs').insert({shipment_id:shipment.id,storage_path:path,file_name:file.name,mime_type:file.type,uploaded_by:me.id,match_method:method,detected_tracking:detectedTracking||null});if(dbErr){await sb.storage.from('proofs').remove([path]).catch(()=>{});throw dbErr}return path}
async function proof(id){const s=shipments.find(x=>x.id===id);if(!s)return;if(s.status!=='ENTREGADO')return showToast('Justificante no disponible','Primero debe registrarse la entrega final.','warn');const input=document.createElement('input');input.type='file';input.multiple=true;input.accept='.pdf,image/jpeg,image/png,image/webp';input.onchange=async()=>{const files=[...(input.files||[])];if(!files.length)return;try{showToast('Subiendo justificantes',files.length+' archivo'+(files.length===1?'':'s')+' para '+s.tracking+'.','info');for(const file of files)await saveProofFile(s,file,'DIRECT',s.tracking);await refresh();await detail(id);showToast('Justificantes guardados',files.length+' archivo'+(files.length===1?'':'s')+' asociado'+(files.length===1?'':'s')+' al expediente.','ok')}catch(e){showToast('Error al subir justificantes',e.message,'warn')}};input.click()}
async function openProofPath(path){const {data,error}=await sb.storage.from('proofs').createSignedUrl(path,120);if(error)return showToast('No se pudo abrir el justificante',error.message,'warn');window.open(data.signedUrl,'_blank','noopener')}
async function openProof(id){const s=shipments.find(x=>x.id===id);if(!s?.proof_path)return alert('Este envío no tiene justificante antiguo.');return openProofPath(s.proof_path)}
function normalizeProofCode(v){return String(v||'').toUpperCase().replace(/[^A-Z0-9]/g,'')}
function deliveredForProofs(){return shipments.filter(s=>s.status==='ENTREGADO').sort((a,b)=>new Date(b.delivered_at||0)-new Date(a.delivered_at||0))}
function matchDeliveredTracking(values){const delivered=deliveredForProofs(),texts=(Array.isArray(values)?values:[values]).map(normalizeProofCode).filter(Boolean);let best=null;for(const s of delivered){const n=normalizeProofCode(s.tracking);if(!n||n.length<5)continue;if(texts.some(t=>t===n||t.includes(n))){if(!best||n.length>normalizeProofCode(best.tracking).length)best=s}}return best}
async function detectProofBarcode(file){if(!('BarcodeDetector'in window)||!file.type.startsWith('image/'))return null;try{const supported=await BarcodeDetector.getSupportedFormats();const formats=['code_128','code_39','code_93','ean_13','ean_8','itf','qr_code'].filter(x=>supported.includes(x));if(!formats.length)return null;const bitmap=await createImageBitmap(file),detector=new BarcodeDetector({formats}),codes=await detector.detect(bitmap);bitmap.close?.();const values=codes.map(x=>x.rawValue||'');const match=matchDeliveredTracking(values);return match?{shipment:match,method:'BARCODE'}:null}catch(e){return null}}
async function detectProofOCR(file,rowIndex){if(!file.type.startsWith('image/')||!window.Tesseract)return null;try{const result=await Tesseract.recognize(file,'eng',{logger:m=>{if(m.status==='recognizing text'&&proofQueue[rowIndex]){proofQueue[rowIndex].progress=Math.round((m.progress||0)*100);renderProofQueue()}}});const text=result?.data?.text||'';const match=matchDeliveredTracking(text);return match?{shipment:match,method:'OCR'}:null}catch(e){console.error(e);return null}}
async function detectProofAssignment(file,rowIndex){const nameMatch=matchDeliveredTracking(file.name);if(nameMatch)return{shipment:nameMatch,method:'FILENAME'};const barcode=await detectProofBarcode(file);if(barcode)return barcode;return detectProofOCR(file,rowIndex)}
function selectProofBatch(){if(!['RECEPCION','ADMIN'].includes(me?.role))return;const input=document.createElement('input');input.type='file';input.multiple=true;input.accept='image/jpeg,image/png,image/webp';input.onchange=()=>processProofBatch([...(input.files||[])]);input.click()}
async function processProofBatch(files){if(proofProcessing)return;if(!files.length)return;if(files.length>30)return showToast('Demasiadas imágenes','Selecciona como máximo 30 fotos por lote.','warn');if(files.reduce((n,f)=>n+f.size,0)>100*1024*1024)return showToast('Lote demasiado grande','El conjunto de fotos supera 100 MB.','warn');for(const f of files)if(f.size>10*1024*1024)return showToast('Archivo demasiado grande',f.name+' supera 10 MB.','warn');proofQueue=files.map(file=>({file,shipmentId:'',tracking:'',method:'',status:'Pendiente',progress:0}));proofProcessing=true;renderProofQueue();for(let i=0;i<proofQueue.length;i++){const row=proofQueue[i];row.status='Analizando';row.progress=0;renderProofQueue();const m=await detectProofAssignment(row.file,i);if(m){row.shipmentId=m.shipment.id;row.tracking=m.shipment.tracking;row.method=m.method;row.status='Detectado'}else{row.status='Revisar';row.method='MANUAL'}renderProofQueue()}proofProcessing=false;renderProofQueue()}
function proofOptions(selected=''){return '<option value="">Seleccionar envío entregado…</option>'+deliveredForProofs().slice(0,500).map(s=>'<option value="'+esc(s.id)+'" '+(s.id===selected?'selected':'')+'>'+esc(s.tracking)+' · '+esc(s.recipient_name||s.customer_name||'')+'</option>').join('')}
function setProofAssignment(i,id){const row=proofQueue[i];if(!row)return;row.shipmentId=id;const s=shipments.find(x=>x.id===id);row.tracking=s?.tracking||'';row.method='MANUAL';row.status=id?'Asignado':'Revisar';renderProofQueue()}
function renderProofQueue(){const box=$('proofqueue');if(!box)return;if(!proofQueue.length){box.innerHTML='<div class="proofempty"><b>Sin fotos pendientes</b><span>Selecciona varias fotos de etiquetas firmadas. El sistema intentará encontrar automáticamente el número de envío.</span></div>';if($('proofuploadall'))$('proofuploadall').disabled=true;return}const unresolved=proofQueue.filter(x=>!x.shipmentId).length;if($('proofuploadall'))$('proofuploadall').disabled=proofProcessing||unresolved>0;box.innerHTML='<div class="proofsummary"><b>'+proofQueue.length+' foto'+(proofQueue.length===1?'':'s')+'</b><span>'+(proofProcessing?'Analizando…':unresolved?unresolved+' necesita'+(unresolved===1?'':'n')+' revisión manual':'Todas asociadas y listas para subir')+'</span></div>'+proofQueue.map((r,i)=>'<div class="proofrow '+(r.shipmentId?'matched':'unmatched')+'"><div class="prooffile"><b>'+esc(r.file.name)+'</b><small>'+Math.round(r.file.size/1024)+' KB · '+esc(r.status)+(r.status==='Analizando'&&r.progress?' '+r.progress+'%':'')+'</small></div><div class="proofmatch"><select class="field" onchange="setProofAssignment('+i+',this.value)">'+proofOptions(r.shipmentId)+'</select><small>'+(r.shipmentId?'Asociación '+esc(r.method):'No se ha podido detectar con seguridad. Selecciona el envío.')+'</small></div></div>').join('')}
function clearProofQueue(){proofQueue=[];proofProcessing=false;renderProofQueue()}
async function uploadProofBatch(){if(proofProcessing)return;if(!proofQueue.length)return;if(proofQueue.some(x=>!x.shipmentId))return showToast('Faltan asociaciones','Revisa las fotos que no tienen envío asignado.','warn');$('proofuploadall').disabled=true;let done=0;try{for(const row of proofQueue){const s=shipments.find(x=>x.id===row.shipmentId);if(!s)throw new Error('No se encuentra el expediente de '+row.file.name);row.status='Subiendo';renderProofQueue();await saveProofFile(s,row.file,row.method,row.tracking);row.status='Guardado';done++;renderProofQueue()}showToast('Lote de justificantes guardado',done+' foto'+(done===1?'':'s')+' asociada'+(done===1?'':'s')+' correctamente.','ok');proofQueue=[];await refresh();await loadProofsView()}catch(e){showToast('Error en la carga',done+' guardadas antes del error. '+e.message,'warn')}finally{proofProcessing=false;renderProofQueue()}}
async function loadProofsView(){if(!['RECEPCION','ADMIN'].includes(me?.role))return;renderProofQueue();const {data,error}=await sb.from('shipment_proofs').select('id,shipment_id,storage_path,file_name,match_method,uploaded_at,shipments(tracking,recipient_name,customer_name)').order('uploaded_at',{ascending:false}).limit(30);if(error){if($('proofrecent'))$('proofrecent').innerHTML='<p class="muted">No se pudieron cargar los justificantes recientes.</p>';return}if($('proofrecent'))$('proofrecent').innerHTML=(data||[]).map(p=>'<button class="proofrecentrow" onclick="openProofPath(\''+esc(p.storage_path)+'\')"><span><b>'+esc(p.shipments?.tracking||'Envío')+'</b><small>'+esc(p.shipments?.recipient_name||p.shipments?.customer_name||'')+'</small></span><span>'+esc(p.file_name)+'</span><span class="tag">'+esc(p.match_method)+'</span><small>'+esc(fmtDate(p.uploaded_at))+'</small></button>').join('')||'<div class="proofempty"><b>Todavía no hay justificantes</b><span>Las fotos firmadas aparecerán aquí después de subirlas.</span></div>'}
function fmtDate(v){return v?new Date(v).toLocaleString():'—'}
async function detail(id){const s=shipments.find(x=>x.id===id);if(!s)return;const [{data:e},{data:proofs}]=await Promise.all([sb.from('events').select('*,profiles(full_name)').eq('shipment_id',id).order('created_at'),sb.from('shipment_proofs').select('*').eq('shipment_id',id).order('uploaded_at',{ascending:false})]);let batch='—';if(s.batch_id){const {data:b}=await sb.from('request_batches').select('batch_code,title').eq('id',s.batch_id).maybeSingle();if(b)batch=(b.title||b.batch_code)+' · '+b.batch_code}const legacy=s.proof_path?'<button class="proofchip" onclick="openProof(\''+s.id+'\')"><b>Justificante anterior</b><small>'+esc(s.proof_name||'Archivo')+'</small></button>':'';const proofList=(proofs||[]).map(p=>'<button class="proofchip" onclick="openProofPath(\''+esc(p.storage_path)+'\')"><b>'+esc(p.file_name)+'</b><small>'+esc(fmtDate(p.uploaded_at))+' · '+esc(p.match_method)+'</small></button>').join('');const proof=proofList||legacy?'<div class="proofchips">'+proofList+legacy+'</div>':'<span class="muted">Sin justificantes adjuntos</span>';const upload=['RECEPCION','ADMIN'].includes(me.role)&&s.status==='ENTREGADO'?'<button class="btn" onclick="proof(\''+s.id+'\')">Añadir foto / justificante</button>':'';const ss=s.stock_snapshot;const stock=ss?'<h3>Datos del stock al crear la solicitud</h3><div class="stockgrid"><div><b>Bulto</b><br>'+esc(ss.tracking||s.tracking)+'</div><div><b>Ubicación</b><br>'+esc(stockLocation(ss)||s.package_location||'—')+'</div><div><b>Recorrido</b><br>'+esc(ss.route||'—')+'</div><div><b>CP destino</b><br>'+esc(ss.destination_postcode||'—')+'</div><div><b>Incidencia origen</b><br>'+esc(ss.incident_type||'—')+'</div><div><b>Agencia</b><br>'+esc(ss.agency||'—')+'</div><div><b>Agencia cargo</b><br>'+esc(ss.charge_agency||'—')+'</div><div><b>Cliente</b><br>'+esc(ss.client_code||'—')+'</div><div><b>Ubicado por</b><br>'+esc(ss.location_user||'—')+'</div><div><b>Fecha ubicación</b><br>'+esc(ss.located_at?fmtDate(ss.located_at):'—')+'</div></div>':'';$('detail').classList.remove('hide');$('detail').innerHTML='<h2>Expediente '+esc(s.tracking)+'</h2><div class="grid"><div><b>Cliente / destinatario</b><br>'+esc(s.customer_name)+'</div><div><b>Ubicación</b><br>'+esc(s.package_location)+'</div><div><b>Estado actual</b><br>'+statusTag(s.status)+'</div><div><b>Prioridad</b><br>'+esc(s.priority||'NORMAL')+'</div><div><b>Lote</b><br>'+esc(batch)+'</div><div><b>Referencia externa</b><br>'+esc(s.external_reference||'—')+'</div></div>'+stock+'<h3>Cadena de custodia</h3><div class="grid"><div><b>Solicitud</b><br>'+esc(fmtDate(s.requested_at))+'</div><div><b>Preparado</b><br>'+esc(fmtDate(s.prepared_at))+'</div><div><b>Salida de Estacionados</b><br>'+esc(fmtDate(s.handoff_at||s.warehouse_at))+'</div><div><b>Recepción confirma</b><br>'+esc(fmtDate(s.reception_confirmed_at||s.reception_at))+'</div><div><b>Entrega final</b><br>'+esc(fmtDate(s.delivered_at))+'</div></div><p><b>Observaciones:</b> '+esc(s.notes||'—')+'</p>'+(s.incident_reason?'<p><b>Incidencia:</b> '+esc(s.incident_reason)+'</p>':'')+(s.recipient_name?'<div class="card"><b>Entrega al destinatario / persona que recoge</b><p>Persona que recoge: '+esc(s.recipient_name)+'</p><p>Identificación: '+esc(s.recipient_id||'No registrada')+'</p><p>Fecha y hora: '+esc(fmtDate(s.delivered_at))+'</p></div>':'')+(s.corrected_at?'<div class="card"><b>Última corrección administrativa</b><p>'+esc(fmtDate(s.corrected_at))+' · '+esc(s.correction_reason||'Sin motivo')+'</p></div>':'')+'<h3>Justificantes de entrega</h3><div class="toolbar">'+upload+'</div>'+proof+'<h3>Trazabilidad cronológica</h3><div class="timeline">'+((e||[]).map(x=>'<div><b>'+esc(x.event_type.replaceAll('_',' '))+'</b><br><span class="muted">'+esc(fmtDate(x.created_at))+' · '+esc(x.profiles?.full_name||'Usuario')+'</span><br>'+esc(x.detail||'')+'</div>').join('')||'<p class="muted">No hay movimientos registrados.</p>')+'</div>';go('shipments');$('detail').scrollIntoView({behavior:'smooth'})}
function printPending(){const rows=workItems();if(!rows.length)return alert('No hay envíos pendientes en la bandeja actual.');const w=window.open('','_blank','width=950,height=900');if(!w)return alert('El navegador ha bloqueado la ventana de impresión.');const body=rows.map(s=>'<tr><td><b>'+esc(s.tracking)+'</b></td><td>'+esc(s.customer_name)+'</td><td>'+esc(s.package_location)+'</td><td>'+esc(labels[s.status]||s.status)+'</td><td>'+esc(s.priority||'NORMAL')+'</td></tr>').join('');const html='<!doctype html><html><head><meta charset="utf-8"><title>Pendientes</title><style>body{font-family:Arial,sans-serif;padding:24px;color:#111}h1{margin-bottom:4px}.muted{color:#666;font-size:12px}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{padding:9px;border-bottom:1px solid #ccc;text-align:left;font-size:12px}th{background:#eee}@media print{body{padding:0}.noprint{display:none}}</style></head><body><button class="noprint" onclick="window.print()">Imprimir</button><h1>Listado de envíos pendientes</h1><div class="muted">'+esc(me.full_name||'Usuario')+' · '+esc(fmtDate(now()))+' · '+rows.length+' envío(s)</div><table><thead><tr><th>Envío</th><th>Cliente</th><th>Ubicación</th><th>Estado</th><th>Prioridad</th></tr></thead><tbody>'+body+'</tbody></table></body></html>';w.document.open();w.document.write(html);w.document.close();setTimeout(()=>w.print(),250)}

function printShipment(id){const s=shipments.find(x=>x.id===id);if(!s)return;const w=window.open('','_blank','width=760,height=900');if(!w)return alert('El navegador ha bloqueado la ventana de impresión.');const html='<!doctype html><html><head><meta charset="utf-8"><title>Expediente '+esc(s.tracking)+'</title><style>body{font-family:Arial,sans-serif;color:#111;padding:28px}h1{font-size:24px;margin:0 0 4px}.muted{color:#666;font-size:12px}.box{border:1px solid #bbb;border-radius:8px;padding:14px;margin:14px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.label{font-size:11px;color:#666;text-transform:uppercase}.value{font-size:15px;font-weight:700;margin-top:3px}.tracking{font-size:28px;letter-spacing:1px}.footer{margin-top:28px;border-top:1px solid #ccc;padding-top:10px;font-size:11px;color:#666}@media print{body{padding:0}.noprint{display:none}}</style></head><body><button class="noprint" onclick="window.print()">Imprimir</button><h1>Expediente de envío</h1><div class="muted">Recepción · Almacén de Estacionados</div><div class="box"><div class="label">Número de envío</div><div class="tracking">'+esc(s.tracking)+'</div></div><div class="grid"><div><div class="label">Cliente / destinatario</div><div class="value">'+esc(s.customer_name)+'</div></div><div><div class="label">Ubicación física</div><div class="value">'+esc(s.package_location)+'</div></div><div><div class="label">Estado</div><div class="value">'+esc(labels[s.status]||s.status)+'</div></div><div><div class="label">Prioridad</div><div class="value">'+esc(s.priority||'NORMAL')+'</div></div><div><div class="label">Fecha solicitud</div><div class="value">'+esc(fmtDate(s.requested_at))+'</div></div><div><div class="label">Fecha entrega</div><div class="value">'+esc(fmtDate(s.delivered_at))+'</div></div></div><div class="box"><div class="label">Observaciones</div><div>'+esc(s.notes||'—')+'</div></div>'+(s.recipient_name?'<div class="box"><div class="label">Entrega final</div><p><b>Persona que recoge:</b> '+esc(s.recipient_name)+'</p><p><b>Identificación:</b> '+esc(s.recipient_id||'No registrada')+'</p><p><b>Fecha y hora:</b> '+esc(fmtDate(s.delivered_at))+'</p></div>':'')+'<div class="footer">Documento generado desde el sistema de trazabilidad · '+esc(fmtDate(now()))+'</div></body></html>';w.document.open();w.document.write(html);w.document.close();setTimeout(()=>w.print(),250)}

function scanKey(e){if(e.key==='Enter'){e.preventDefault();scanShipment()}}
function clearScanner(){if($('scaninput'))$('scaninput').value='';if($('scanresult'))$('scanresult').innerHTML='';$('scaninput')?.focus()}
function scanAction(s){if(['ESTACIONADOS','ADMIN'].includes(me.role)){if(s.status==='SOLICITADO')return ['Marcar Localizando',()=>setStatus(s.id,'LOCALIZANDO')];if(s.status==='LOCALIZANDO')return ['Marcar Preparado',()=>prepare(s.id)];if(['PREPARADO','INCIDENCIA'].includes(s.status))return ['Entregar a Recepción',()=>handoff(s.id)]}if(['RECEPCION','ADMIN'].includes(me.role)){if(s.status==='PENDIENTE_RECEPCION')return ['Confirmar recepción',()=>confirmReception(s.id)];if(s.status==='EN_RECEPCION')return ['Entrega final',()=>deliver(s.id)]}return null}
async function scanShipment(){const input=$('scaninput'),code=input?.value.trim();if(!code)return;const s=shipments.find(x=>String(x.tracking).trim().toLowerCase()===code.toLowerCase());input.value='';if(!s){const st=await lookupStock(code);if(st){$('scanresult').innerHTML=stockCardHtml(st,['RECEPCION','ADMIN'].includes(me.role)?'<button id="scancreaterequest" class="btn ok">Crear solicitud</button>':'');if($('scancreaterequest'))$('scancreaterequest').onclick=()=>applyStockToNew(st);scanHistory.unshift({code,status:'Localizado en stock',at:new Date()});renderScanHistory();input.focus();return}$('scanresult').innerHTML='<div class="card"><b>No localizado</b><p class="muted">El número '+esc(code)+' no figura ni como expediente ni en el stock actual.</p></div>';scanHistory.unshift({code,status:'No encontrado',at:new Date()});renderScanHistory();input.focus();return}const action=scanAction(s);$('scanresult').innerHTML='<div class="card"><h3>'+esc(s.tracking)+'</h3><p><b>'+esc(s.customer_name)+'</b><br>'+esc(s.package_location)+'</p><p>Estado: '+statusTag(s.status)+'</p><div class="actions"><button class="btn btn2" data-sid="'+esc(s.id)+'" onclick="detail(this.dataset.sid)">Ver expediente</button>'+(action?'<button id="scanaction" class="btn ok">'+esc(action[0])+'</button>':'<span class="muted">No hay una acción automática disponible para tu perfil en este estado.</span>')+'</div></div>';if(action){$('scanaction').onclick=async()=>{await action[1]();scanHistory.unshift({code:s.tracking,status:action[0],at:new Date()});renderScanHistory();setTimeout(()=>{$('scaninput')?.focus()},100)}}else{scanHistory.unshift({code:s.tracking,status:labels[s.status]||s.status,at:new Date()});renderScanHistory()}input.focus()}
function renderScanHistory(){if(!$('scanhistory'))return;$('scanhistory').innerHTML=scanHistory.slice(0,10).map(x=>'<div><b>'+esc(x.code)+'</b><br><span class="muted">'+esc(x.at.toLocaleTimeString())+' · '+esc(x.status)+'</span></div>').join('')||'<p class="muted">Todavía no se han escaneado envíos.</p>'}

function reportItems(){const df=$('reportfrom')?.value||'',dt=$('reportto')?.value||'';return shipments.filter(s=>{const day=(s.requested_at||'').slice(0,10);return(!df||day>=df)&&(!dt||day<=dt)})}
function avgHours(rows,a,b){const v=rows.filter(s=>s[a]&&s[b]).map(s=>(new Date(s[b])-new Date(s[a]))/3600000).filter(x=>x>=0);return v.length?(v.reduce((p,n)=>p+n,0)/v.length).toFixed(1)+' h':'—'}
function renderReports(){if(me?.role!=='ADMIN'||!$('reportcards'))return;const f=reportItems(),del=f.filter(s=>s.status==='ENTREGADO'),open=f.filter(s=>s.status!=='ENTREGADO'),incident=f.filter(s=>s.status==='INCIDENCIA'||s.incident_reason);$('reportcards').innerHTML='<div class="card"><div class="muted">Solicitudes</div><div class="metric">'+f.length+'</div></div><div class="card"><div class="muted">Entregados</div><div class="metric">'+del.length+'</div></div><div class="card"><div class="muted">Pendientes</div><div class="metric">'+open.length+'</div></div><div class="card"><div class="muted">Incidencias</div><div class="metric">'+incident.length+'</div></div><div class="card"><div class="muted">Urgentes</div><div class="metric">'+f.filter(s=>s.priority==='URGENTE').length+'</div></div>';$('reportstatus').innerHTML=Object.keys(labels).map(k=>'<p><b>'+esc(labels[k])+'</b>: '+f.filter(s=>s.status===k).length+'</p>').join('');$('reporttimes').innerHTML='<p><b>Solicitud → Recepción:</b> '+avgHours(f,'requested_at','reception_at')+'</p><p><b>Recepción → Entrega:</b> '+avgHours(f,'reception_at','delivered_at')+'</p><p><b>Solicitud → Entrega:</b> '+avgHours(f,'requested_at','delivered_at')+'</p>'}
function setReportRange(days){if(!$('reportfrom')||!$('reportto'))return;if(!days){$('reportfrom').value='';$('reportto').value=''}else{const e=new Date(),s=new Date();s.setDate(e.getDate()-(days-1));$('reportfrom').value=s.toISOString().slice(0,10);$('reportto').value=e.toISOString().slice(0,10)}renderReports()}
function exportReportCSV(){const f=reportItems(),h=['Envio','Cliente','Ubicacion','Prioridad','Estado','Solicitud','Recepcion','Entrega','Recogido por'];const rows=f.map(s=>[s.tracking,s.customer_name,s.package_location,s.priority,s.status,s.requested_at,s.reception_at||'',s.delivered_at||'',s.recipient_name||'']);downloadCSV([h,...rows],'informe_envios_'+new Date().toISOString().slice(0,10)+'.csv')}
function downloadCSV(rows,name){const csv=rows.map(r=>r.map(csvCell).join(';')).join('\n');const a=document.createElement('a');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

function importShipments(){if(!['RECEPCION','ADMIN'].includes(me?.role))return alert('Tu perfil no puede importar solicitudes.');const input=document.createElement('input');input.type='file';input.accept='.csv,.txt,text/csv,text/plain';input.onchange=async()=>{const f=input.files?.[0];if(!f)return;if(f.size>5*1024*1024)return alert('El archivo supera 5 MB.');const text=await f.text();const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!lines.length)return alert('El archivo está vacío.');if(lines.length>5000)return alert('La importación admite un máximo de 5.000 líneas.');const rows=[],errors=[];for(let i=0;i<lines.length;i++){const sep=lines[i].includes(';')?';':',';const p=lines[i].split(sep).map(x=>x.trim().replace(/^"|"$/g,''));if(i===0&&/env[ií]o|tracking|seguimiento/i.test(p[0]||''))continue;if(p.length<3||!p[0]||!p[1]||!p[2]){errors.push('Línea '+(i+1));continue}rows.push({tracking:p[0],customer_name:p[1],package_location:p[2],notes:p[3]||'',priority:(p[4]||'NORMAL').toUpperCase()==='URGENTE'?'URGENTE':'NORMAL'})}if(errors.length)return alert('Hay líneas con formato incorrecto: '+errors.slice(0,10).join(', '));if(!rows.length)return alert('No se encontraron envíos válidos.');const existing=new Set(shipments.map(s=>String(s.tracking).trim().toLowerCase())),seen=new Set(),dups=[];for(const r of rows){const k=r.tracking.toLowerCase();if(existing.has(k)||seen.has(k))dups.push(r.tracking);seen.add(k)}if(dups.length)return alert('Importación cancelada. Hay números duplicados: '+dups.slice(0,10).join(', '));if(!confirm('Se importarán '+rows.length+' solicitudes. ¿Continuar?'))return;const {data,error}=await sb.rpc('create_manual_requests',{p_rows:rows,p_title:'Importación '+f.name,p_notes:null,p_source:f.name});if(error)return alert(error.message);await refresh();alert((data?.count||rows.length)+' solicitudes importadas correctamente'+(data?.batch_code?' · '+data.batch_code:'')+'.')};input.click()}
function csvCell(v){let s=String(v??'');if(/^[\t\r\n ]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
function exportCSV(){const h=['Envio','Cliente','Ubicacion','Prioridad','Estado','Solicitado','Entregado','Recogido por','Identificacion'];const rows=searchResults().map(s=>[s.tracking,s.customer_name,s.package_location,s.priority,s.status,s.requested_at,s.delivered_at||'',s.recipient_name||'',s.recipient_id||'']);const csv=[h,...rows].map(r=>r.map(csvCell).join(';')).join('\n');const a=document.createElement('a');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'}));a.href=url;a.download='envios_'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function strongPassword(p){if(typeof p!=='string'||p.length<12||p.length>128)return false;let n=0;if(/[a-záéíóúüñ]/.test(p))n++;if(/[A-ZÁÉÍÓÚÜÑ]/.test(p))n++;if(/\d/.test(p))n++;if(/[^A-Za-zÁÉÍÓÚÜÑáéíóúüñ0-9]/.test(p))n++;return n>=3}
async function adminCall(body){const {data:{session}}=await sb.auth.getSession();if(!session)return {error:'La sesión ha caducado. Vuelve a iniciar sesión.'};try{const r=await fetch(SB_URL+'/functions/v1/admin-users',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+session.access_token,'apikey':SB_KEY},body:JSON.stringify(body)});const x=await r.json().catch(()=>({error:'Respuesta no válida del servidor.'}));if(!r.ok&&!x.error)x.error='Operación no autorizada.';return x}catch(e){return {error:'No se pudo conectar con la administración de usuarios.'}}}
async function createUser(){const b={action:'create',full_name:$('ufull').value.trim(),email:$('uemail').value.trim(),password:$('upass').value,role:$('urole').value};if(!b.full_name||!b.email||!strongPassword(b.password))return alert('Completa los datos. La contraseña debe tener al menos 12 caracteres y combinar 3 tipos: mayúsculas, minúsculas, números o símbolos.');const x=await adminCall(b);if(x.error)return alert(x.error);$('ufull').value=$('uemail').value=$('upass').value='';loadUsers();alert('Usuario creado.')}
async function loadUsers(){if(me?.role!=='ADMIN')return;const x=await adminCall({action:'list'});if(x.error)return alert(x.error);const data=x.data||[];$('users').innerHTML='<div class="tablewrap"><table><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Activo</th><th>Último acceso</th><th>Acciones</th></tr>'+data.map(u=>'<tr><td>'+esc(u.full_name||'—')+'</td><td>'+esc(u.email||'—')+'</td><td>'+esc(u.role)+'</td><td>'+(u.active?'Sí':'No')+'</td><td>'+esc(u.last_sign_in_at?fmtDate(u.last_sign_in_at):'Nunca')+'</td><td><div class="actions"><button class="btn btn2" data-uid="'+esc(u.id)+'" onclick="editUser(this.dataset.uid)">Editar</button><button class="btn" data-uid="'+esc(u.id)+'" onclick="resetUserPassword(this.dataset.uid)">Contraseña</button><button class="btn danger" data-uid="'+esc(u.id)+'" onclick="deleteUser(this.dataset.uid)">Eliminar</button></div></td></tr>').join('')+'</table></div>'}
async function editUser(id){const x=await adminCall({action:'list'});const u=(x.data||[]).find(v=>v.id===id);if(!u)return alert('Usuario no encontrado.');const name=prompt('Nombre y apellidos:',u.full_name||'');if(name===null||!name.trim())return;const role=(prompt('Rol: RECEPCION, ESTACIONADOS o ADMIN',u.role)||'').trim().toUpperCase();if(!['RECEPCION','ESTACIONADOS','ADMIN'].includes(role))return alert('Rol no válido.');const active=confirm('Pulsa Aceptar para dejar el usuario ACTIVO.\nPulsa Cancelar para dejarlo INACTIVO.');if(id===me.id&&!active)return alert('No puedes desactivar tu propio usuario desde esta pantalla.');const r=await adminCall({action:'update',id,full_name:name.trim(),role,active});if(r.error)return alert(r.error);if(id===me.id){me.full_name=name.trim();me.role=role;$('identity').textContent=me.full_name+' · '+me.role}await loadUsers();alert('Usuario actualizado.')}
async function resetUserPassword(id){const p=prompt('Nueva contraseña temporal (mínimo 12 caracteres):');if(!p)return;if(!strongPassword(p))return alert('La contraseña debe tener al menos 12 caracteres y combinar 3 tipos: mayúsculas, minúsculas, números o símbolos.');const r=await adminCall({action:'reset_password',id,password:p});if(r.error)return alert(r.error);alert('Contraseña actualizada.')}
async function deleteUser(id){if(id===me.id)return alert('No puedes eliminar tu propia cuenta.');if(!confirm('¿Eliminar este usuario? Solo será posible si nunca ha intervenido en solicitudes, lotes, incidencias o movimientos.'))return;const r=await adminCall({action:'delete',id});if(r.error)return alert(r.error);await loadUsers();alert('Usuario eliminado.')} 
async function changePassword(){const p=$('newpass').value;if(!strongPassword(p))return alert('La contraseña debe tener al menos 12 caracteres y combinar 3 tipos: mayúsculas, minúsculas, números o símbolos.');const {error}=await sb.auth.updateUser({password:p});alert(error?error.message:'Contraseña cambiada.');$('newpass').value=''}
async function logout(){await sb.auth.signOut();location.reload()}sb.auth.getSession().then(({data})=>{if(data.session)loadApp(data.session.user)});